.card {
  padding: 16px;       /* all four sides */
  padding: 8px 24px;   /* top/bottom, left/right */
}

.card {
  border: 2px solid black;
  border-radius: 12px; /* rounded corners */
}

.card {
  margin: 24px;      /* gap on all sides */
  margin: 0 auto;    /* centers a fixed-width block */
}

/* display-only: the width gotcha */
.box {
  width: 200px;   /* content only! */
  padding: 20px;  /* +40 */
  border: 5px solid black; /* +10 */
} /* renders 250px wide */

* {
  box-sizing: border-box; /* apply everywhere */
}
.box {
  width: 200px;   /* now the FULL box */
  padding: 20px;
  border: 5px solid black;
} /* renders exactly 200px */

/* display-only: margins collapse */
.top { margin-bottom: 20px; }
.bottom { margin-top: 30px; }
/* gap between them: 30px, not 50px */
